cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <style>
    :root {
      --bg: #f5f7fb;
      --surface: #ffffff;
      --text: #0d1321;
      --muted: #4f5d75;
      --line: #dde3ee;
      --accent: #2563eb;
      --accent-soft: #eaf1ff;
      --hover: #f0f4fa;
      --radius: 16px;
      --shadow: 0 8px 30px rgba(13, 19, 33, 0.06);
      --max: 1160px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      background: var(--bg);
      color: var(--text);
      font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      line-height: 1.65;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(var(--max), calc(100% - 2rem));
      margin-inline: auto;
    }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 20;
      background: rgba(255, 255, 255, 0.95);
      backdrop-filter: blur(8px);
      border-bottom: 1px solid var(--line);
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 72px;
      gap: 1rem;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 0.7rem;
      font-weight: 800;
      letter-spacing: -0.02em;
      font-size: 1.1rem;
    }

    .brand-badge {
      width: 30px;
      height: 30px;
      border-radius: 9px;
      background: linear-gradient(145deg, #2563eb, #1d4ed8);
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.25);
    }

    .menu {
      display: flex;
      align-items: center;
      gap: 1.2rem;
      color: var(--muted);
      font-weight: 550;
      position: relative;
    }

    .menu > a,
    .dropdown-toggle {
      padding: 0.5rem 0.3rem;
      border-radius: 8px;
      cursor: pointer;
      border: 0;
      background: transparent;
      color: inherit;
      font: inherit;
    }

    .dropdown {
      position: relative;
    }

    .mega {
      position: absolute;
      top: calc(100% + 0.6rem);
      left: 0;
      width: min(680px, 90vw);
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: 14px;
      box-shadow: var(--shadow);
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
      padding: 1rem;
      opacity: 0;
      pointer-events: none;
      transform: translateY(8px);
      transition: 180ms ease;
    }

    .dropdown.open .mega,
    .dropdown:focus-within .mega,
    .dropdown:hover .mega {
      opacity: 1;
      pointer-events: auto;
      transform: translateY(0);
    }

    .mega h4 {
      margin: 0 0 0.45rem;
      font-size: 0.85rem;
      color: #20293b;
      letter-spacing: 0.02em;
      text-transform: uppercase;
    }

    .mega a {
      display: block;
      padding: 0.3rem 0;
      font-size: 0.93rem;
      color: var(--muted);
    }

    .hero {
      padding: 3rem 0 1.3rem;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.28rem 0.72rem;
      border-radius: 999px;
      background: #edf2ff;
      color: #334155;
      font-size: 0.8rem;
      font-weight: 650;
    }

    h1 {
      margin: 0.95rem 0 0.55rem;
      font-size: clamp(2rem, 4.2vw, 3.35rem);
      line-height: 1.12;
      letter-spacing: -0.035em;
    }

    .subtitle {
      max-width: 760px;
      color: var(--muted);
      margin: 0;
      font-size: 1.08rem;
    }

    .filters {
      margin-top: 1.7rem;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 0.8rem;
      align-items: center;
    }

    .pills {
      display: flex;
      flex-wrap: wrap;
      gap: 0.55rem;
    }

    .pill {
      border: 1px solid var(--line);
      border-radius: 999px;
      background: var(--surface);
      color: #2b364c;
      padding: 0.45rem 0.86rem;
      font-size: 0.89rem;
      font-weight: 600;
      cursor: pointer;
      transition: all 140ms ease;
    }

    .pill:hover { background: var(--hover); }

    .pill.active {
      border-color: var(--accent);
      background: var(--accent-soft);
      color: #133ea5;
    }

    .search {
      width: min(320px, 100%);
      position: relative;
    }

    .search input {
      width: 100%;
      border: 1px solid var(--line);
      border-radius: 12px;
      background: var(--surface);
      padding: 0.66rem 0.85rem;
      font-size: 0.95rem;
      color: var(--text);
      outline: none;
      transition: border-color 120ms ease;
    }

    .search input:focus { border-color: #8caeff; }

    .section-title {
      margin: 2.2rem 0 1rem;
      font-size: 1.45rem;
      letter-spacing: -0.02em;
    }

    .featured {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
      margin-bottom: 0.5rem;
    }

    .featured .card {
      min-height: 330px;
      border: 1px solid #ced8eb;
      background: linear-gradient(160deg, #ffffff, #f6f9ff);
    }

    .card {
      border: 1px solid var(--line);
      background: var(--surface);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 1rem;
      display: flex;
      flex-direction: column;
      transition: transform 180ms ease, box-shadow 180ms ease;
    }

    .card:hover {
      transform: translateY(-4px);
      box-shadow: 0 16px 36px rgba(13, 19, 33, 0.11);
    }

    .meta {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 0.6rem;
      font-size: 0.82rem;
      color: #44516b;
      margin-bottom: 0.75rem;
    }

    .tag {
      display: inline-flex;
      align-items: center;
      border-radius: 999px;
      background: #eef3ff;
      color: #1d4ed8;
      font-size: 0.75rem;
      font-weight: 700;
      padding: 0.22rem 0.6rem;
      border: 1px solid #d5e2ff;
      letter-spacing: 0.01em;
    }

    .card h3 {
      margin: 0.15rem 0 0.55rem;
      font-size: 1.24rem;
      line-height: 1.28;
      letter-spacing: -0.015em;
    }

    .excerpt {
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .stats {
      margin-top: 0.75rem;
      padding: 0.7rem;
      border-radius: 12px;
      background: #f0f5ff;
      border: 1px solid #dbe7ff;
      color: #1f3b84;
      font-size: 0.85rem;
      font-weight: 650;
      line-height: 1.5;
    }

    .author {
      margin-top: auto;
      padding-top: 0.85rem;
      display: flex;
      align-items: center;
      gap: 0.62rem;
    }

    .avatar {
      width: 34px;
      height: 34px;
      border-radius: 50%;
      background: linear-gradient(135deg, #bac9e9, #859fdb);
      color: #0f254f;
      display: grid;
      place-items: center;
      font-size: 0.78rem;
      font-weight: 800;
    }

    .author span {
      font-size: 0.84rem;
      color: #334155;
      font-weight: 600;
    }

    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
      margin-top: 0.7rem;
    }

    .empty {
      margin-top: 1rem;
      border: 1px dashed #bcc7dd;
      border-radius: 14px;
      padding: 1rem;
      text-align: center;
      color: #475569;
      background: #fbfcff;
      display: none;
    }

    .show-more-wrap {
      margin: 1.25rem 0 0;
      text-align: center;
    }

    .btn {
      border: 1px solid #bdd0ff;
      background: #edf3ff;
      color: #1f4bc0;
      border-radius: 12px;
      padding: 0.62rem 1rem;
      font-weight: 700;
      cursor: pointer;
      transition: all 140ms ease;
    }

    .btn:hover { background: #dfeaff; }

    .btn:disabled {
      opacity: 0.45;
      cursor: not-allowed;
    }

    .cta {
      margin: 3rem 0 2.3rem;
      border-radius: 20px;
      background: linear-gradient(140deg, #0d1321, #1e293b);
      color: #dbe7ff;
      padding: 1.6rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .cta h3 {
      margin: 0;
      font-size: 1.35rem;
      color: #fff;
      letter-spacing: -0.015em;
    }

    .footer {
      border-top: 1px solid var(--line);
      padding: 1.4rem 0 2rem;
      color: #4b5563;
      font-size: 0.92rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 0.7rem;
    }

    @media (max-width: 1024px) {
      .featured,
      .news-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
      .filters { grid-template-columns: 1fr; }
      .search { width: 100%; }
    }

    @media (max-width: 720px) {
      .menu { display: none; }
      .featured,
      .news-grid {
        grid-template-columns: 1fr;
      }
      .hero { padding-top: 2rem; }
      .section-title { margin-top: 1.6rem; }
      .mega { width: min(500px, 94vw); grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="container nav">
      <a href="#" class="brand" aria-label="DeployCloud Home">
        <span class="brand-badge" aria-hidden="true"></span>
        <span>DeployCloud</span>
      </a>

      <nav class="menu" aria-label="Main navigation">
        <a href="#">Blog</a>
        <div class="dropdown" id="productsDropdown">
          <button class="dropdown-toggle" aria-haspopup="true" aria-expanded="false">Products ▾</button>
          <div class="mega" role="menu" aria-label="Products menu">
            <div>
              <h4>AI Cloud</h4>
              <a href="#">Agent Runtime</a>
              <a href="#">AI Gateway</a>
              <a href="#">Inference Router</a>
            </div>
            <div>
              <h4>Core Platform</h4>
              <a href="#">Deploy Pipelines</a>
              <a href="#">Edge Functions</a>
              <a href="#">Observability</a>
            </div>
            <div>
              <h4>Security</h4>
              <a href="#">Sandboxing</a>
              <a href="#">Threat Controls</a>
              <a href="#">Compliance Center</a>
            </div>
          </div>
        </div>

        <div class="dropdown" id="resourcesDropdown">
          <button class="dropdown-toggle" aria-haspopup="true" aria-expanded="false">Resources ▾</button>
          <div class="mega" role="menu" aria-label="Resources menu">
            <div>
              <h4>Company</h4>
              <a href="#">About</a>
              <a href="#">Careers</a>
              <a href="#">Press</a>
            </div>
            <div>
              <h4>Learn</h4>
              <a href="#">Documentation</a>
              <a href="#">Guides</a>
              <a href="#">Webinars</a>
            </div>
            <div>
              <h4>Open Source</h4>
              <a href="#">SDKs</a>
              <a href="#">Templates</a>
              <a href="#">Community Projects</a>
            </div>
          </div>
        </div>

        <a href="#">Docs</a>
      </nav>
    </div>
  </header>

  <main class="container">
    <section class="hero">
      <span class="eyebrow">DeployCloud Engineering</span>
      <h1>Discover the latest in web development</h1>
      <p class="subtitle">Engineering insights, product updates, and community stories from DeployCloud — built for developers, engineering teams, and technical decision-makers.</p>

      <div class="filters" aria-label="Post filtering controls">
        <div class="pills" id="categoryPills"></div>
        <label class="search" for="searchInput">
          <input id="searchInput" type="search" placeholder="Search posts by keyword..." aria-label="Search posts" />
        </label>
      </div>
    </section>

    <section aria-labelledby="featured-heading">
      <h2 class="section-title" id="featured-heading">Featured Articles</h2>
      <div class="featured" id="featuredArticles"></div>
    </section>

    <section aria-labelledby="latest-heading">
      <h2 class="section-title" id="latest-heading">Latest News</h2>
      <div class="news-grid" id="latestNewsGrid"></div>
      <div class="empty" id="emptyState">No results found. Try a different category or search keyword.</div>
      <div class="show-more-wrap">
        <button class="btn" id="showMoreBtn">Show more posts</button>
      </div>
    </section>

    <section class="cta" aria-label="Call to action">
      <div>
        <h3>Ship faster with DeployCloud</h3>
        <p style="margin: .35rem 0 0; color: #c5d2f3;">Build, deploy, and scale modern apps with an AI-native cloud platform.</p>
      </div>
      <button class="btn" style="background:#2563eb;color:#fff;border-color:#3b82f6;">Start Deploying</button>
    </section>
  </main>

  <footer class="container footer">
    <span>© 2026 DeployCloud, Inc. All rights reserved.</span>
    <span>Status: All Systems Normal</span>
  </footer>

  <script>
    const categories = [
      'All Posts',
      'Engineering',
      'Community',
      'Company News',
      'Customers',
      'Security'
    ];

    const featuredPosts = [
      {
        category: 'Engineering',
        date: 'April 18, 2026',
        title: 'Agentic Infrastructure is reshaping modern delivery pipelines',
        excerpt: 'Over 30% of deployments are now initiated by coding agents — a 1000% increase from six months ago — and agent-driven workloads are 20 times more likely to call AI inference.',
        author: 'Maya L.',
        initials: 'ML',
        stats: ['30% of deployments initiated by coding agents', '1000% increase from six months ago', '20 times more likely to call AI inference']
      },
      {
        category: 'Engineering',
        date: 'April 10, 2026',
        title: 'A new programming model for durable execution',
        excerpt: 'Design workflows that survive retries, crashes, and long-running state transitions without compromising developer experience.',
        author: 'Ethan K.',
        initials: 'EK'
      },
      {
        category: 'Security',
        date: 'March 29, 2026',
        title: 'Agent responsibly: guardrails for autonomous shipping',
        excerpt: 'Policy-driven controls for identity, sandboxing, and rollout governance keep high-velocity AI workflows reliable and compliant.',
        author: 'Priya N.',
        initials: 'PN'
      }
    ];

    const latestPosts = [
      { category: 'Engineering', date: 'April 10, 2026', title: 'A new programming model for durable execution', excerpt: 'Move from scripts to durable orchestration with resumable, observable execution primitives.', author: 'Ethan K.', initials: 'EK' },
      { category: 'Security', date: 'April 7, 2026', title: 'Zero Data Retention on AI Gateway', excerpt: 'New controls ensure sensitive prompts and responses remain transient across the inference path.', author: 'Priya N.', initials: 'PN' },
      { category: 'Engineering', date: 'April 4, 2026', title: 'Optimizing Sandbox snapshots', excerpt: 'Snapshotting changes reduced cold start times and improved consistency in ephemeral builds.', author: 'Jon C.', initials: 'JC' },
      { category: 'Community', date: 'March 31, 2026', title: 'How a startup made a blog platform work for humans and AI alike', excerpt: 'A practical look at metadata, content structure, and retrieval-first publishing patterns.', author: 'Leah M.', initials: 'LM' },
      { category: 'Customers', date: 'March 28, 2026', title: 'Making build tool 96% faster with agents, sandboxes, and humans', excerpt: 'A customer story about reducing CI bottlenecks using adaptive agent routing and cache-aware workflows.', author: 'Ari S.', initials: 'AS' },
      { category: 'Company News', date: 'March 20, 2026', title: 'Unified reporting for all AI Gateway usage', excerpt: 'Teams now get end-to-end cost, model, and latency analytics in a single operational view.', author: 'Nina R.', initials: 'NR' },
      { category: 'Engineering', date: 'March 16, 2026', title: 'Event-driven deployments at global scale', excerpt: 'Behind the scenes of routing deployment events through a reliable multi-region queue.', author: 'Omar T.', initials: 'OT' },
      { category: 'Community', date: 'March 9, 2026', title: 'Building with DeployCloud templates', excerpt: 'A walkthrough of common stacks and what developers customize first in production.', author: 'Sara V.', initials: 'SV' },
      { category: 'Company News', date: 'March 2, 2026', title: 'DeployCloud raises the bar on platform reliability', excerpt: 'New release trains and progressive policies increase confidence for critical production rollouts.', author: 'Ben P.', initials: 'BP' }
    ];

    const pageSize = 6;
    let activeCategory = 'All Posts';
    let searchTerm = '';
    let visibleCount = pageSize;

    const categoryPillsEl = document.getElementById('categoryPills');
    const searchInputEl = document.getElementById('searchInput');
    const featuredEl = document.getElementById('featuredArticles');
    const latestGridEl = document.getElementById('latestNewsGrid');
    const emptyStateEl = document.getElementById('emptyState');
    const showMoreBtnEl = document.getElementById('showMoreBtn');

    function createCard(post, isFeatured = false) {
      const card = document.createElement('article');
      card.className = 'card';
      card.innerHTML = `
        <div class="meta">
          <span class="tag">${post.category}</span>
          <span>${post.date}</span>
        </div>
        <h3>${post.title}</h3>
        <p class="excerpt">${post.excerpt}</p>
        ${post.stats && isFeatured ? `<div class="stats">${post.stats.map(stat => `• ${stat}`).join('<br>')}</div>` : ''}
        <div class="author">
          <div class="avatar" aria-hidden="true">${post.initials}</div>
          <span>${post.author}</span>
        </div>
      `;
      return card;
    }

    function matchesFilters(post) {
      const categoryOk = activeCategory === 'All Posts' || post.category === activeCategory;
      const q = searchTerm.trim().toLowerCase();
      if (!q) return categoryOk;
      const haystack = `${post.title} ${post.excerpt} ${post.category} ${post.author}`.toLowerCase();
      return categoryOk && haystack.includes(q);
    }

    function renderFeatured() {
      featuredEl.innerHTML = '';
      featuredPosts.forEach(post => featuredEl.appendChild(createCard(post, true)));
    }

    function renderCategoryPills() {
      categoryPillsEl.innerHTML = '';
      categories.forEach(category => {
        const btn = document.createElement('button');
        btn.className = `pill${category === activeCategory ? ' active' : ''}`;
        btn.type = 'button';
        btn.textContent = category;
        btn.addEventListener('click', () => {
          activeCategory = category;
          visibleCount = pageSize;
          renderCategoryPills();
          renderLatest();
        });
        categoryPillsEl.appendChild(btn);
      });
    }

    function renderLatest() {
      const filtered = latestPosts.filter(matchesFilters);
      const visiblePosts = filtered.slice(0, visibleCount);

      latestGridEl.innerHTML = '';
      visiblePosts.forEach(post => latestGridEl.appendChild(createCard(post)));

      const hasResults = filtered.length > 0;
      emptyStateEl.style.display = hasResults ? 'none' : 'block';
      showMoreBtnEl.style.display = hasResults ? 'inline-flex' : 'none';
      showMoreBtnEl.disabled = visibleCount >= filtered.length;
      showMoreBtnEl.textContent = visibleCount >= filtered.length ? 'No more posts' : 'Show more posts';
    }

    showMoreBtnEl.addEventListener('click', () => {
      visibleCount += pageSize;
      renderLatest();
    });

    searchInputEl.addEventListener('input', (event) => {
      searchTerm = event.target.value;
      visibleCount = pageSize;
      renderLatest();
    });

    function wireDropdown(id) {
      const dropdown = document.getElementById(id);
      const toggle = dropdown.querySelector('.dropdown-toggle');
      toggle.addEventListener('click', () => {
        const isOpen = dropdown.classList.toggle('open');
        toggle.setAttribute('aria-expanded', String(isOpen));
      });
      document.addEventListener('click', (event) => {
        if (!dropdown.contains(event.target)) {
          dropdown.classList.remove('open');
          toggle.setAttribute('aria-expanded', 'false');
        }
      });
    }

    wireDropdown('productsDropdown');
    wireDropdown('resourcesDropdown');
    renderFeatured();
    renderCategoryPills();
    renderLatest();
  </script>
</body>
</html>
