  <script>
    const categories = [
      'All Posts',
      'Engineering',
      'Community',
      'Company News',
      'Customers',
      'Security'
    ];

    const featuredPosts = [
      {
        category: 'Engineering',
        date: 'April 18, 2026',
        title: 'Agentic Infrastructure is reshaping modern delivery pipelines',
        excerpt: 'Over 30% of deployments are now initiated by coding agents — a 1000% increase from six months ago — and agent-driven workloads are 20 times more likely to call AI inference.',
        author: 'Maya L.',
        initials: 'ML',
        stats: ['30% of deployments initiated by coding agents', '1000% increase from six months ago', '20 times more likely to call AI inference']
      },
      {
        category: 'Engineering',
        date: 'April 10, 2026',
        title: 'A new programming model for durable execution',
        excerpt: 'Design workflows that survive retries, crashes, and long-running state transitions without compromising developer experience.',
        author: 'Ethan K.',
        initials: 'EK'
      },
      {
        category: 'Security',
        date: 'March 29, 2026',
        title: 'Agent responsibly: guardrails for autonomous shipping',
        excerpt: 'Policy-driven controls for identity, sandboxing, and rollout governance keep high-velocity AI workflows reliable and compliant.',
        author: 'Priya N.',
        initials: 'PN'
      }
    ];

    const latestPosts = [
      { category: 'Engineering', date: 'April 10, 2026', title: 'A new programming model for durable execution', excerpt: 'Move from scripts to durable orchestration with resumable, observable execution primitives.', author: 'Ethan K.', initials: 'EK' },
      { category: 'Security', date: 'April 7, 2026', title: 'Zero Data Retention on AI Gateway', excerpt: 'New controls ensure sensitive prompts and responses remain transient across the inference path.', author: 'Priya N.', initials: 'PN' },
      { category: 'Engineering', date: 'April 4, 2026', title: 'Optimizing Sandbox snapshots', excerpt: 'Snapshotting changes reduced cold start times and improved consistency in ephemeral builds.', author: 'Jon C.', initials: 'JC' },
      { category: 'Community', date: 'March 31, 2026', title: 'How a startup made a blog platform work for humans and AI alike', excerpt: 'A practical look at metadata, content structure, and retrieval-first publishing patterns.', author: 'Leah M.', initials: 'LM' },
      { category: 'Customers', date: 'March 28, 2026', title: 'Making build tool 96% faster with agents, sandboxes, and humans', excerpt: 'A customer story about reducing CI bottlenecks using adaptive agent routing and cache-aware workflows.', author: 'Ari S.', initials: 'AS' },
      { category: 'Company News', date: 'March 20, 2026', title: 'Unified reporting for all AI Gateway usage', excerpt: 'Teams now get end-to-end cost, model, and latency analytics in a single operational view.', author: 'Nina R.', initials: 'NR' },
      { category: 'Engineering', date: 'March 16, 2026', title: 'Event-driven deployments at global scale', excerpt: 'Behind the scenes of routing deployment events through a reliable multi-region queue.', author: 'Omar T.', initials: 'OT' },
      { category: 'Community', date: 'March 9, 2026', title: 'Building with DeployCloud templates', excerpt: 'A walkthrough of common stacks and what developers customize first in production.', author: 'Sara V.', initials: 'SV' },
      { category: 'Company News', date: 'March 2, 2026', title: 'DeployCloud raises the bar on platform reliability', excerpt: 'New release trains and progressive policies increase confidence for critical production rollouts.', author: 'Ben P.', initials: 'BP' }
    ];

    const pageSize = 6;
    let activeCategory = 'All Posts';
    let searchTerm = '';
    let visibleCount = pageSize;

    const categoryPillsEl = document.getElementById('categoryPills');
    const searchInputEl = document.getElementById('searchInput');
    const featuredEl = document.getElementById('featuredArticles');
    const latestGridEl = document.getElementById('latestNewsGrid');
    const emptyStateEl = document.getElementById('emptyState');
    const showMoreBtnEl = document.getElementById('showMoreBtn');

    function createCard(post, isFeatured = false) {
      const card = document.createElement('article');
      card.className = 'card';
      card.innerHTML = `
        <div class="meta">
          <span class="tag">${post.category}</span>
          <span>${post.date}</span>
        </div>
        <h3>${post.title}</h3>
        <p class="excerpt">${post.excerpt}</p>
        ${post.stats && isFeatured ? `<div class="stats">${post.stats.map(stat => `• ${stat}`).join('<br>')}</div>` : ''}
        <div class="author">
          <div class="avatar" aria-hidden="true">${post.initials}</div>
          <span>${post.author}</span>
        </div>
      `;
      return card;
    }

    function matchesFilters(post) {
      const categoryOk = activeCategory === 'All Posts' || post.category === activeCategory;
      const q = searchTerm.trim().toLowerCase();
      if (!q) return categoryOk;
      const haystack = `${post.title} ${post.excerpt} ${post.category} ${post.author}`.toLowerCase();
      return categoryOk && haystack.includes(q);
    }

    function renderFeatured() {
      featuredEl.innerHTML = '';
      featuredPosts.forEach(post => featuredEl.appendChild(createCard(post, true)));
    }

    function renderCategoryPills() {
      categoryPillsEl.innerHTML = '';
      categories.forEach(category => {
        const btn = document.createElement('button');
        btn.className = `pill${category === activeCategory ? ' active' : ''}`;
        btn.type = 'button';
        btn.textContent = category;
        btn.addEventListener('click', () => {
          activeCategory = category;
          visibleCount = pageSize;
          renderCategoryPills();
          renderLatest();
        });
        categoryPillsEl.appendChild(btn);
      });
    }

    function renderLatest() {
      const filtered = latestPosts.filter(matchesFilters);
      const visiblePosts = filtered.slice(0, visibleCount);

      latestGridEl.innerHTML = '';
      visiblePosts.forEach(post => latestGridEl.appendChild(createCard(post)));

      const hasResults = filtered.length > 0;
      emptyStateEl.style.display = hasResults ? 'none' : 'block';
      showMoreBtnEl.style.display = hasResults ? 'inline-flex' : 'none';
      showMoreBtnEl.disabled = visibleCount >= filtered.length;
      showMoreBtnEl.textContent = visibleCount >= filtered.length ? 'No more posts' : 'Show more posts';
    }

    showMoreBtnEl.addEventListener('click', () => {
      visibleCount += pageSize;
      renderLatest();
    });

    searchInputEl.addEventListener('input', (event) => {
      searchTerm = event.target.value;
      visibleCount = pageSize;
      renderLatest();
    });

    function wireDropdown(id) {
      const dropdown = document.getElementById(id);
      const toggle = dropdown.querySelector('.dropdown-toggle');
      toggle.addEventListener('click', () => {
        const isOpen = dropdown.classList.toggle('open');
        toggle.setAttribute('aria-expanded', String(isOpen));
      });
      document.addEventListener('click', (event) => {
        if (!dropdown.contains(event.target)) {
          dropdown.classList.remove('open');
          toggle.setAttribute('aria-expanded', 'false');
        }
      });
    }

    wireDropdown('productsDropdown');
    wireDropdown('resourcesDropdown');
    renderFeatured();
    renderCategoryPills();
    renderLatest();
  </script>
